// msg.payload = array 12 nilai uint16 dari slave.
//
// PENTING: enam register pertama adalah int16 BERTANDA berskala x100.
// Library Modbus mengembalikan word mentah sebagai uint16, jadi tanda
// harus dipulihkan sendiri. Tanpa ini, -1.5 A terbaca sebagai 654.36 A
// dan tidak ada yang tampak error.
const r = msg.payload;

if (!Array.isArray(r) || r.length < 12) {
    node.warn('Jawaban tidak lengkap: ' + JSON.stringify(r));
    return null;
}

const s16 = (v) => (v > 32767) ? v - 65536 : v;
const bit = (w, b) => ((w >> b) & 1) === 1;

const st = r[8];

msg.payload = {
    rectifier: {
        voltage: s16(r[0]) / 100,
        current: s16(r[1]) / 100
    },
    baterai: {
        voltage: s16(r[2]) / 100,
        current: s16(r[3]) / 100
    },
    load: {
        voltage: s16(r[4]) / 100,
        current: s16(r[5]) / 100
    },
    di_word: r[6],
    do_word: r[7],
    device: {
        eeprom:    bit(st, 0),
        ads1115:   bit(st, 1),
        mcp4725:   bit(st, 2),
        ioexp_do:  bit(st, 3),
        ioexp_di:  bit(st, 4),
        ads131m04: bit(st, 5),
        adc_run:   bit(st, 6),
        semua_ok:  (st & 0x7F) === 0x7F
    },
    adc_sps: r[9],
    adc_overrun: r[10],
    uptime_s: r[11]
};

msg.topic = 'recticon/ukur';
return msg;

// msg.payload = array 16 boolean.
// Indeks 0-7  -> GPA0..GPA7 chip MCP23S17 digital input
// Indeks 8-15 -> GPB0..GPB7
const b = msg.payload;

if (!Array.isArray(b) || b.length < 16) {
    node.warn('Jawaban DI tidak lengkap: ' + JSON.stringify(b));
    return null;
}

msg.payload = {
    gpa: b.slice(0, 8),
    gpb: b.slice(8, 16)
};

msg.topic = 'recticon/di';
return msg;

// msg.payload = array 8 boolean -> GPA0..GPA7 chip MCP23S17 digital output
const b = msg.payload;

if (!Array.isArray(b) || b.length < 8) {
    node.warn('Jawaban coil tidak lengkap: ' + JSON.stringify(b));
    return null;
}

msg.payload = { relay: b.slice(0, 8) };
msg.topic = 'recticon/do';
return msg;

// msg.payload = array 3 nilai uint16.
// Ketiganya tidak bertanda, jadi tidak perlu konversi seperti input register.
const r = msg.payload;

if (!Array.isArray(r) || r.length < 3) {
    node.warn('Jawaban HR tidak lengkap: ' + JSON.stringify(r));
    return null;
}

msg.payload = {
    dac_setpoint: r[0],   // 0..4095
    do_word:      r[1],   // bitmap 8 relay
    slave_addr:   r[2]    // semestinya 10 - kalau bukan, port-nya bukan yang kita kira
};

msg.topic = 'recticon/setelan';
return msg;
